 * @param {number} page The one-based page number.
 * @param {number} size The number of items per page.
 * @param {Array<Object>} data The full dataset.
 * @returns {Array<Object>} The paginated data.
 */
function paginate(page, size, data) {
  // Validate page and size: must be positive integers
  if (!Number.isInteger(page) || page <= 0 || !Number.isInteger(size) || size <= 0) {
    return [];
  }

  const totalItems = data.length;
  const startIndex = (page - 1) * size;
  const endIndex = startIndex + size;

  // Check for out-of-range page
  if (startIndex >= totalItems) {
    return [];
  }

  // Slice the data and return
  return data.slice(startIndex, endIndex);
}

module.exports = {
  paginate: paginate
};"}

